const tabs = [
  { icon: Home, label: "Inicio" },
  { icon: Compass, label: "Explorar" },
  { icon: Library, label: "Biblioteca" },
  { icon: Search, label: "Buscar" },
];

interface GlassTabBarProps {
  bg?: Wallpaper;
  blur?: number;
  opacity?: number;
  shine?: number;
}

export default function GlassTabBar({
  bg = "aurora",
  blur = 20,
  opacity = 12,
  shine = 25,
}: GlassTabBarProps) {
  const glass = { bg, blur, opacity, shine };
  const [active, setActive] = useState(0);

  return (
    <Stage {...glass}>
      <div className="absolute inset-x-0 bottom-6 flex justify-center">
        <div onMouseMove={track} className="lg-glass flex rounded-full p-1">
          {tabs.map(({ icon: Icon, label }, i) => (
            <motion.button
              key={label}
              type="button"
              aria-pressed={active === i}
              onClick={() => setActive(i)}
              whileTap={{ scale: 0.92 }}
              transition={spring}
              className="lg-text relative z-[3] flex h-[54px] w-[74px] flex-col items-center justify-center gap-0.5"
            >
              {active === i && (
                // La key cambia en cada pulsación para repetir el estirón de la píldora
                <motion.span
                  key={`pill-${active}`}
                  layoutId="lg-tab-pill"
                  className="absolute inset-0 rounded-full"
                  initial={{ scaleX: 1 }}
                  animate={{ scaleX: [1, 1.15, 1] }}
                  transition={{
                    layout: spring,
                    scaleX: { duration: 0.45, ease: [0.25, 0.1, 0.25, 1] },
                  }}
                  style={{
                    background: "rgba(255,255,255,.22)",
                    boxShadow: "inset 0 1px 0 rgba(255,255,255,.55), 0 2px 8px rgba(0,0,0,.08)",
                  }}
                />
              )}
              <Icon className="relative h-[22px] w-[22px]" strokeWidth={1.75} />
              <span className="relative text-[11px] font-medium">{label}</span>
            </motion.button>
          ))}
        </div>
      </div>
    </Stage>
  );
}

