}

export default function GlassToggle({
  label = "Modo concentración",
  bg = "aurora",
  blur = 20,
  opacity = 12,
  shine = 25,
}: GlassToggleProps) {
  const glass = { bg, blur, opacity, shine };
  const [on, setOn] = useState(true);
  const [moving, setMoving] = useState(false);

  // La gota se estira un momento mientras se desplaza
  const flip = () => {
    setMoving(true);
    setOn((o) => !o);
    setTimeout(() => setMoving(false), 180);
  };

  return (
    <Stage {...glass}>
      <div className="flex flex-col items-center gap-5">
        <motion.button
          type="button"
          role="switch"
          aria-checked={on}
          aria-label={label}
          onClick={flip}
          onMouseMove={track}
          whileTap={{ scale: 0.95 }}
          transition={spring}
          className="lg-glass rounded-full"
          style={{
            width: 64,
            height: 28,
            transition: "background-color .3s",
            ...(on ? { background: "#34c759" } : {}),
          }}
        >
          <motion.span
            className="absolute left-[2px] top-[2px] z-[3] block h-6 w-6 rounded-full"
            animate={{ x: on ? 36 : 0, scaleX: moving ? 1.3 : 1 }}
            transition={spring}
            style={{
              originX: on ? 1 : 0,
              background: "radial-gradient(circle at 35% 30%, #fff 0%, rgba(255,255,255,.92) 55%, rgba(240,240,245,.85) 100%)",
              boxShadow: "0 3px 8px rgba(0,0,0,.18), inset 0 -1px 2px rgba(0,0,0,.06), inset 0 1px 1px #fff",
            }}
          />
        </motion.button>
        <span className="lg-text text-[15px] font-medium">{label}</span>
      </div>
    </Stage>
  );
}

