  const c = 2 * Math.PI * r;
  return (
    <svg width={r * 2 + sw * 2} height={r * 2 + sw * 2} className="-rotate-90">
      <circle cx={r + sw} cy={r + sw} r={r} fill="none" stroke="currentColor" strokeOpacity={0.2} strokeWidth={sw} />
