        cx={r + sw}
        cy={r + sw}
        r={r}
        fill="none"
        stroke={color}
        strokeWidth={sw}
        strokeLinecap="round"
        strokeDasharray={c}
        initial={{ strokeDashoffset: c }}
        animate={{ strokeDashoffset: c * (1 - p) }}
        transition={{ ...spring, stiffness: 60, damping: 18 }}
      />
    </svg>
  );
}

