css:
.uv-gmr {
  --c1: #34c759;
  --c2: #0a84ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --bl: 18px;
  /* desenfoque */
  --op: 0.18;
  /* opacidad del cristal */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-gmr {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 20em;
  height: 14em;
  border-radius: 1.6em;
  overflow: hidden;
  color: #fff;
  isolation: isolate;
  height: 15em;
  color: #1d1d1f;
}

.uv-gmr .mp {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.uv-gmr .rt {
  stroke: var(--c2);
  stroke-dasharray: 420;
  stroke-dashoffset: 420;
  animation: uv-gmr calc(1.4s / var(--k)) cubic-bezier(.22,1,.36,1) .2s forwards;
}

.uv-gmr .pn {
  position: absolute;
  left: .7em;
  right: .7em;
  bottom: .7em;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: .2em .6em;
  padding: .8em .9em;
  border-radius: 1.3em;
  background: rgba(255,255,255,calc(var(--op) + .1));
  -webkit-backdrop-filter: blur(calc(var(--bl) * 1.4)) saturate(1.8);
  backdrop-filter: blur(calc(var(--bl) * 1.4)) saturate(1.8);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.6),inset 0 0 0 1px rgba(255,255,255,.25),0 1.2em 2.6em -.8em rgba(0,0,0,.4);
  background: rgba(255,255,255,calc(var(--op) + .45));
}

.uv-gmr .ds {
  grid-column: 1/-1;
  margin: 0;
  font-size: .78em;
  font-weight: 600;
  opacity: .7;
}

.uv-gmr .et {
  margin: 0;
  display: flex;
  align-items: baseline;
  gap: .4em;
}

.uv-gmr .et b {
  font-size: 1.4em;
  letter-spacing: -.02em;
  color: var(--c1);
  display: none;
}

.uv-gmr .et span {
  font-size: .78em;
  opacity: .65;
}

.uv-gmr .md {
  grid-column: 1;
  display: flex;
  gap: .25em;
  padding: .2em;
  border-radius: 2em;
  background: rgba(0,0,0,.06);
  width: max-content;
}

.uv-gmr .md label {
  position: relative;
  cursor: pointer;
}

.uv-gmr .md input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
}

.uv-gmr .md span {
  display: grid;
  place-items: center;
  width: 2.1em;
  height: 1.7em;
  border-radius: 2em;
  color: rgba(0,0,0,.55);
  transition: all calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-gmr .md svg {
  width: 1.1em;
  height: 1.1em;
}

.uv-gmr .md input:checked + span {
  color: #1d1d1f;
  background: #fff;
  box-shadow: 0 .1em .3em rgba(0,0,0,.15);
}

.uv-gmr .md input:focus-visible + span {
  outline: 2px solid var(--c2);
  outline-offset: 1px;
}

.uv-gmr .go {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  grid-row: 2/4;
  grid-column: 2;
  align-self: end;
  padding: .75em 1.4em;
  border-radius: 2em;
  font-weight: 800;
  color: #fff;
  background: var(--c1);
  box-shadow: 0 .5em 1em -.5em var(--c1);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-gmr .go:active {
  transform: scale(.94);
}

.uv-gmr .go:focus-visible {
  outline: 2px solid var(--c2);
  outline-offset: 2px;
}

.uv-gmr:has(label:nth-of-type(1) input:checked) .t1,.uv-gmr:has(label:nth-of-type(2) input:checked) .t2,.uv-gmr:has(label:nth-of-type(3) input:checked) .t3 {
  display: inline;
  animation: uv-gmr-t calc(0.35s / var(--k)) cubic-bezier(.22,1,.36,1);
}

@keyframes uv-gmr {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes uv-gmr-t {
  from {
    opacity: 0;
    transform: translateY(.3em);
  }
}

