  opacity: 1;
}

.uv-gfb .fb {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  right: 1em;
  bottom: 1em;
  display: grid;
  place-items: center;
  width: 3.4em;
  height: 3.4em;
  border-radius: 50%;
  color: #fff;
  background: color-mix(in srgb,var(--c1) 75%,transparent);
  -webkit-backdrop-filter: blur(var(--bl)) saturate(1.8);
  backdrop-filter: blur(var(--bl)) saturate(1.8);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.5),inset 0 0 0 1px rgba(255,255,255,.3),0 .8em 1.6em -.6em var(--c1);
