const fmt=n=>(Math.round(n*10)/10||0).toLocaleString(lang,{minimumFractionDigits:1,maximumFractionDigits:1})+"°";
const step=()=>{const t=tgt();v=(v+(t-bx)*.07)*.84;bx+=v;el.style.setProperty("--bx",bx.toFixed(3)+"em");if(Math.abs(v)>.0004||Math.abs(t-bx)>.002)raf=requestAnimationFrame(step);else raf=0};
const go=()=>{if(rm){bx=tgt();el.style.setProperty("--bx",bx+"em");return}if(!raf)raf=requestAnimationFrame(step)};
const set=n=>{a=Math.max(-12,Math.min(12,n));el.style.setProperty("--a",a.toFixed(2)+"deg");const s=fmt(a);out.textContent=s;lv.setAttribute("aria-valuenow",a.toFixed(1));lv.setAttribute("aria-valuetext",s);el.classList.toggle("ok",Math.abs(a)<.3);go()};
lv.addEventListener("pointerdown",e=>{lv.setPointerCapture(e.pointerId);dr={x:e.clientX,a:a,s:el.getBoundingClientRect().width/el.offsetWidth||1}});
lv.addEventListener("pointermove",e=>{if(dr)set(dr.a+(e.clientX-dr.x)/dr.s*.05)});
const up=()=>{dr=null};lv.addEventListener("pointerup",up);lv.addEventListener("pointercancel",up);
