.uvq11-hg {
  --c1: #f2c17d;
  --c2: #6b3f2a;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --du: 20;
  /* duración */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq11-hg {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 20em;
  height: 14em;
  border-radius: 1.6em;
  overflow: hidden;
  color: #fff;
  isolation: isolate;
  -webkit-user-select: none;
  user-select: none;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.6em;
  background: radial-gradient(45% 55% at 30% 50%,rgba(255,196,140,.55),transparent 70%),linear-gradient(160deg,#c0573e,#7a2f3b 55%,#3d1d33);
}

.uvq11-hg .hb {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: block;
  width: 6.6em;
  height: 11.2em;
  border-radius: 1em;
}

.uvq11-hg .hb:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
  outline-offset: 4px;
}

.uvq11-hg .hb::after {
  content: "";
  position: absolute;
  left: 10%;
  right: 10%;
  bottom: -.5em;
  height: .9em;
  border-radius: 50%;
  background: radial-gradient(closest-side,rgba(40,10,10,.5),transparent);
  z-index: -1;
}

.uvq11-hg .fl {
  display: block;
  width: 100%;
  height: 100%;
  transition: transform calc(0.8s / var(--k)) cubic-bezier(.5,-.25,.3,1.35);
}

.uvq11-hg .fl.go {
  transform: rotate(180deg);
}

.uvq11-hg .fl.nt {
  transition: none;
}

.uvq11-hg .hb:active .fl {
  scale: .97;
}

.uvq11-hg svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.uvq11-hg .po {
  stroke: var(--c2);
  stroke-width: 3.4;
  stroke-linecap: round;
}

.uvq11-hg .sd {
  fill: var(--c1);
}

.uvq11-hg .sb {
  fill: color-mix(in srgb,var(--c1) 88%,#7a4a20);
}

.uvq11-hg .fa {
  fill: none;
  stroke: var(--c1);
  stroke-width: 1.6;
  stroke-dasharray: 2 2.5;
  opacity: 0;
}

.uvq11-hg.run .fa {
  opacity: 1;
  animation: uvq11-hg calc(0.4s / var(--k)) linear infinite;
}

.uvq11-hg .gs {
  fill: rgba(255,255,255,.1);
  stroke: rgba(255,255,255,.8);
  stroke-width: 1.3;
}

.uvq11-hg .hl {
  fill: none;
  stroke: rgba(255,255,255,.6);
  stroke-width: 2.6;
  stroke-linecap: round;
}

.uvq11-hg .tx {
  display: grid;
  gap: .3em;
}

.uvq11-hg .tm {
  font-size: 2.6em;
  font-weight: 250;
  letter-spacing: -.03em;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.uvq11-hg .tx span {
  font-size: .78em;
  font-weight: 600;
  opacity: .75;
}

.uvq11-hg.done .tm {
  animation: uvq11-hg-d calc(0.9s / var(--k)) cubic-bezier(.25,.1,.25,1) 3;
}

@keyframes uvq11-hg {
  to {
    stroke-dashoffset: -9;
  }
}

@keyframes uvq11-hg-d {
  50% {
    opacity: .35;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq11-hg,.uvq11-hg *,.uvq11-hg *::before,.uvq11-hg *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

