.uvq11-clo {
  --c1: #f6d55c;
  --c2: #9cc5a1;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq11-clo {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 20em;
  height: 14em;
  border-radius: 1.6em;
  overflow: hidden;
  color: #fff;
  isolation: isolate;
  -webkit-user-select: none;
  user-select: none;
  color: #203026;
  background: radial-gradient(45% 60% at 18% 10%,rgba(255,255,255,.65),transparent 70%),linear-gradient(180deg,color-mix(in srgb,var(--c2) 80%,#fff),var(--c2) 78%,transparent 78%),linear-gradient(170deg,transparent 40%,rgba(0,0,0,.06) 41%,transparent 43%),linear-gradient(180deg,#f4f1ec,#ddd7cd);
}

.uvq11-clo .sn {
  position: absolute;
  left: 0;
  top: 0;
  width: 12em;
  height: 14em;
}

.uvq11-clo .pl {
  position: absolute;
  left: 1.4em;
  top: 9.6em;
  width: 9.2em;
  height: 1.3em;
  border-radius: 50%;
  background: radial-gradient(ellipse at 50% 35%,#fff,#ece8e2 70%,#cfc9c0);
  box-shadow: 0 .22em 0 #d6d0c7,0 .7em 1em -.3em rgba(0,0,0,.3);
}

.uvq11-clo .sm {
  position: absolute;
  left: 5.4em;
  top: 10.5em;
  width: 1.2em;
  height: 1.8em;
  background: linear-gradient(90deg,#d4cfc6,#fff,#d4cfc6);
}

.uvq11-clo .ft {
  position: absolute;
  left: 3.6em;
  top: 12em;
  width: 4.8em;
  height: .9em;
  border-radius: 50%;
  background: radial-gradient(ellipse at 50% 30%,#fff,#d8d2c9);
  box-shadow: 0 .4em .6em -.2em rgba(0,0,0,.3);
}

.uvq11-clo .tt {
  position: absolute;
  left: 2.6em;
  top: 8.1em;
  width: 6.8em;
  height: 2.2em;
}

.uvq11-clo .sd {
  position: absolute;
  left: 0;
  right: 0;
  top: .7em;
  bottom: 0;
  border-radius: 0 0 50% 50%/0 0 .8em .8em;
  background: repeating-linear-gradient(90deg,rgba(0,0,0,.08) 0 .1em,transparent .1em .45em),linear-gradient(90deg,#a5652f,#e3a866 30%,#f1bf7f 50%,#c98a49 80%,#a5652f);
}

.uvq11-clo .tp {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 1.5em;
  box-sizing: border-box;
  border-radius: 50%;
  border: .22em solid #e2a866;
  background: radial-gradient(ellipse at 42% 38%,#fff9cf 0 7%,var(--c1) 32%,color-mix(in srgb,var(--c1) 78%,#c58b00) 80%);
}

.uvq11-clo .mr {
  position: absolute;
  width: 1.05em;
  height: 1em;
  border-radius: 50% 50% 45% 45%;
  background: radial-gradient(circle at 40% 30%,#fff 0 22%,#f7efe2 50%,#e0b06a 78%,#b9773a);
}

.uvq11-clo .mr::before {
  content: "";
  position: absolute;
  left: 35%;
  top: -.28em;
  width: .32em;
  height: .42em;
  border-radius: 50% 50% 40% 40%/70% 70% 30% 30%;
  background: linear-gradient(#c98a49,#f2dcc0);
}

.uvq11-clo .lm {
  position: absolute;
  left: 2.75em;
  top: .25em;
  width: 1.1em;
  height: .6em;
  border-radius: 50%;
  background: repeating-conic-gradient(#fff3a0 0 25deg,#fff 25deg 30deg);
  box-shadow: 0 0 0 .08em #f2c200;
}

.uvq11-clo .vp {
  position: absolute;
  left: 4em;
  top: 4.2em;
  width: 4em;
  height: 3.6em;
  pointer-events: none;
}

.uvq11-clo .vp i {
  position: absolute;
  bottom: 0;
  width: .8em;
  height: 2.6em;
  border-radius: 50%;
  border-left: .18em solid rgba(255,255,255,.75);
  filter: blur(1.5px);
  opacity: 0;
}

.uvq11-clo .vp i:nth-child(1) {
  left: .4em;
}

.uvq11-clo .vp i:nth-child(2) {
  left: 1.6em;
  animation-delay: calc(0.5s / var(--k))!important;
}

.uvq11-clo .vp i:nth-child(3) {
  left: 2.8em;
  animation-delay: calc(1s / var(--k))!important;
}

.uvq11-clo.on .vp i {
  animation: uvq11-clo calc(2.2s / var(--k)) cubic-bezier(.25,.1,.25,1) infinite;
}

.uvq11-clo .dm {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: absolute;
  left: 1.2em;
  top: 2.4em;
  width: 9.6em;
  height: 7.6em;
  border-radius: 50% 50% 7% 7%/66% 66% 7% 7%;
  transform-origin: 100% 100%;
  background: linear-gradient(90deg,rgba(255,255,255,.22),rgba(255,255,255,.03) 22%,transparent 60%,rgba(255,255,255,.16) 88%,rgba(255,255,255,.3));
  -webkit-backdrop-filter: blur(.6px) saturate(1.15) brightness(1.04);
  backdrop-filter: blur(.6px) saturate(1.15) brightness(1.04);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.55),inset .7em 0 1em -.5em rgba(255,255,255,.55),inset -.6em 0 1em -.6em rgba(255,255,255,.4),inset 0 -.3em .2em -.1em rgba(255,255,255,.7),0 1em 1.4em -1em rgba(0,0,0,.35);
  transition: transform calc(0.7s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq11-clo .dm::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  -webkit-backdrop-filter: blur(3px) brightness(1.08);
  backdrop-filter: blur(3px) brightness(1.08);
  -webkit-mask: radial-gradient(closest-side,transparent 72%,#000 98%);
  mask: radial-gradient(closest-side,transparent 72%,#000 98%);
}

.uvq11-clo .dm::after {
  content: "";
  position: absolute;
  left: 14%;
  top: 16%;
  width: 12%;
  height: 52%;
  border-radius: 50%;
  background: linear-gradient(180deg,rgba(255,255,255,.85),rgba(255,255,255,0));
  transform: rotate(-14deg);
  filter: blur(.5px);
}

.uvq11-clo .kn {
  position: absolute;
  left: 50%;
  top: -1.05em;
  width: 1.3em;
  height: 1.3em;
  margin-left: -.65em;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%,#fff 0 18%,rgba(255,255,255,.35) 40%,rgba(200,230,215,.5) 80%);
  box-shadow: inset 0 -.15em .2em rgba(0,0,0,.15),0 .2em .3em rgba(0,0,0,.15);
}

.uvq11-clo .kn::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -.3em;
  width: .5em;
  height: .45em;
  margin-left: -.25em;
  background: rgba(255,255,255,.45);
}

.uvq11-clo .dm:hover {
  transform: translateY(-.2em);
}

.uvq11-clo .dm:focus-visible {
  outline: 2px solid #203026;
  outline-offset: 3px;
}

.uvq11-clo.on .dm {
  transform: translate(2.6em,-3.4em) rotate(13deg);
}

.uvq11-clo .lb {
  position: absolute;
  left: 12.3em;
  top: 3.6em;
  width: 7em;
}

.uvq11-clo .nm {
  margin: 0;
  font-size: 1.15em;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -.01em;
}

.uvq11-clo .pr {
  margin: .3em 0 .9em;
  font-size: .9em;
  font-weight: 600;
  opacity: .75;
}

.uvq11-clo .ch {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: inline-flex;
