  justify-content: center;
  gap: .4em;
  padding: .55em 1em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 650;
  line-height: 1;
  color: #fff;
  background: rgba(255,255,255,.16);
  -webkit-backdrop-filter: blur(10px) saturate(1.7);
  backdrop-filter: blur(10px) saturate(1.7);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.55),inset 0 -1px 0 rgba(255,255,255,.1),inset 0 0 0 1px rgba(255,255,255,.24),0 .5em 1.2em -.5em rgba(0,0,0,.45);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1),background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
