  font-size: .72em;
}

.uvq11-clo .ch:hover {
  background: rgba(255,255,255,.8);
}

.uvq11-clo .ch:focus-visible {
  outline-color: #203026;
}

.uvq11-clo .ch[aria-pressed=true] {
  color: #fff;
  background: #203026;
}

@keyframes uvq11-clo {
  0% {
    opacity: 0;
    transform: translateY(.6em) scaleX(1);
  }
  35% {
    opacity: .8;
  }
  100% {
    opacity: 0;
    transform: translateY(-2.4em) scaleX(-1);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq11-clo,.uvq11-clo *,.uvq11-clo *::before,.uvq11-clo *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

