document.querySelectorAll(".uvq11-clo").forEach(el => {
  const bs=el.querySelectorAll(".dm,.ch");const set=o=>{el.classList.toggle("on",o);bs.forEach(b=>b.setAttribute("aria-pressed",String(o)))};bs.forEach(b=>b.addEventListener("click",()=>set(!el.classList.contains("on"))));el.addEventListener("keydown",e=>{if(e.key==="Escape")set(false)})
});

