.uvq11-lens {
  --c1: #8b5cf6;
  --c2: #2ee59d;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq11-lens {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 20em;
  height: 14em;
  border-radius: 1.6em;
  overflow: hidden;
  color: #fff;
  isolation: isolate;
  -webkit-user-select: none;
  user-select: none;
  --mx: 0;
  --my: 0;
  background: radial-gradient(50% 60% at 30% 40%,#2a2a30,#0c0c0e 75%);
}

.uvq11-lens .ln {
  position: absolute;
  left: .9em;
  top: 1.5em;
  width: 11em;
  height: 11em;
  border-radius: 50%;
  background: repeating-conic-gradient(#1a1a1d 0 2deg,#303035 2deg 4deg);
  box-shadow: 0 1em 2em -.6em rgba(0,0,0,.9),inset 0 0 0 .08em #555;
}

.uvq11-lens .ln::before {
  content: "";
  position: absolute;
  inset: .6em;
  border-radius: 50%;
  background: radial-gradient(circle,#0d0d10 60%,#1d1d22 61%,#141417 100%);
  box-shadow: 0 0 0 .06em #77777f,inset 0 0 0 .05em #c33;
}

.uvq11-lens .tx {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.uvq11-lens text {
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: .8px;
  fill: #c9ccd3;
}

.uvq11-lens .gl {
  position: absolute;
  inset: 1.9em;
  border-radius: 50%;
  overflow: hidden;
  background: radial-gradient(circle,#06070b 0 30%,#0e1219 62%,#1d2433 88%,#07080b 100%);
  box-shadow: inset 0 0 0 .14em #050506,inset 0 0 1.2em rgba(0,0,0,.9);
}

.uvq11-lens .ir {
  position: absolute;
  inset: 9%;
  width: 82%;
  height: 82%;
}

.uvq11-lens .bl {
  fill: #17171b;
}

.uvq11-lens .ed {
  fill: none;
  stroke: rgba(255,255,255,.1);
  stroke-width: .6;
}

.uvq11-lens .gl i {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq11-lens .ct {
  left: 38%;
  top: 38%;
  width: 24%;
  height: 24%;
  background: radial-gradient(circle,color-mix(in srgb,var(--c1) 70%,transparent),transparent 70%);
  transform: translate(calc(var(--mx) * -.3em),calc(var(--my) * -.3em));
}

.uvq11-lens .r1 {
  inset: 4%;
  background: conic-gradient(from 200deg,transparent 0 30deg,color-mix(in srgb,var(--c1) 85%,transparent) 60deg,transparent 110deg,transparent 220deg,color-mix(in srgb,var(--c2) 70%,transparent) 250deg,transparent 290deg);
  -webkit-mask: radial-gradient(closest-side,transparent 82%,#000 88% 92%,transparent 97%);
  mask: radial-gradient(closest-side,transparent 82%,#000 88% 92%,transparent 97%);
  transform: rotate(calc(var(--mx) * 25deg));
}

.uvq11-lens .r2 {
  left: 56%;
  top: 58%;
  width: 1.2em;
  height: 1.2em;
  background: radial-gradient(circle,color-mix(in srgb,var(--c2) 80%,#fff) 0 15%,color-mix(in srgb,var(--c2) 60%,transparent) 40%,transparent 70%);
  transform: translate(calc(var(--mx) * .7em),calc(var(--my) * .7em));
}

.uvq11-lens .r3 {
  left: 30%;
  top: 62%;
  width: .5em;
  height: .5em;
  background: radial-gradient(circle,#ffcf7a,transparent 70%);
  transform: translate(calc(var(--mx) * .4em),calc(var(--my) * .4em));
}

.uvq11-lens .sb {
  left: 20%;
  top: 16%;
  width: 1.7em;
  height: 1.05em;
  border-radius: .35em;
  background: linear-gradient(160deg,rgba(255,255,255,.95),rgba(255,255,255,.55));
  filter: blur(.4px);
  transform: translate(calc(var(--mx) * -1em),calc(var(--my) * -1em)) skewX(-8deg);
}

.uvq11-lens .pn {
  position: absolute;
  left: 12.6em;
  top: 1.1em;
  width: 6.7em;
}

.uvq11-lens .fm {
  margin: 0;
  font-size: .62em;
  font-weight: 700;
  letter-spacing: .14em;
  color: #9a9aa5;
}

.uvq11-lens .fv {
  display: block;
  margin: .05em 0 .35em;
  font-size: 1.65em;
  font-weight: 250;
  letter-spacing: -.02em;
}

.uvq11-lens .vf {
  position: relative;
  height: 3.6em;
  border-radius: .6em;
  overflow: hidden;
  background: linear-gradient(180deg,#22354a,#0f1722);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.15);
}

.uvq11-lens .vf i {
  position: absolute;
  left: var(--x);
  top: var(--y);
  width: calc((.3em + 1.5em * var(--bk)) * var(--z));
  aspect-ratio: 1;
  border-radius: 50%;
  translate: -50% -50%;
  background: radial-gradient(circle,color-mix(in srgb,var(--c) 45%,transparent) 0 55%,var(--c) 66%,transparent 72%);
  filter: blur(calc(var(--bk) * 1.2px));
  opacity: calc(.5 + .45 * var(--bk));
  transition: all calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq11-lens .vf b {
  position: absolute;
  left: 50%;
  bottom: 0;
  width: 1.3em;
  height: 1.9em;
  margin-left: -.65em;
  border-radius: .65em .65em 0 0;
  background: #0a0d12;
  box-shadow: 0 -1.15em 0 -.25em #0a0d12;
}

.uvq11-lens .vf::after {
  content: "";
  position: absolute;
  inset: .4em;
  background: linear-gradient(#fff,#fff) 0 0/.5em 1px,linear-gradient(#fff,#fff) 0 0/1px .5em,linear-gradient(#fff,#fff) 100% 0/.5em 1px,linear-gradient(#fff,#fff) 100% 0/1px .5em,linear-gradient(#fff,#fff) 0 100%/.5em 1px,linear-gradient(#fff,#fff) 0 100%/1px .5em,linear-gradient(#fff,#fff) 100% 100%/.5em 1px,linear-gradient(#fff,#fff) 100% 100%/1px .5em;
  background-repeat: no-repeat;
  opacity: .7;
}

.uvq11-lens .ap {
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: .3em;
  margin-top: .55em;
}

.uvq11-lens label {
  position: relative;
  cursor: pointer;
}

.uvq11-lens input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
}

.uvq11-lens label span {
  display: block;
  padding: .45em 0;
  border-radius: .5em;
  text-align: center;
  font-size: .62em;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: #c9ccd3;
  background: rgba(255,255,255,.07);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.12);
  transition: all calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq11-lens label:hover span {
  background: rgba(255,255,255,.14);
}

.uvq11-lens input:checked+span {
  color: #111;
  background: #f2f2f5;
  box-shadow: 0 0 0 1px #fff,0 .3em .8em -.3em var(--c1);
}

.uvq11-lens input:focus-visible+span {
  outline: 2px solid #fff;
  outline-offset: 2px;
}

.uvq11-lens label:active span {
  transform: scale(.94);
}

@media (prefers-reduced-motion:reduce) {
  .uvq11-lens,.uvq11-lens *,.uvq11-lens *::before,.uvq11-lens *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
