document.querySelectorAll(".uvq11-wg").forEach(el => {
  const rm=matchMedia("(prefers-reduced-motion: reduce)").matches;const n=el.querySelector(".n");let c=3,t=0;
const set=(v,p)=>{const o=c;c=Math.max(0,Math.min(8,v));n.textContent=String(c);el.style.setProperty("--lv",String(c/8));el.classList.toggle("full",c===8);if(p&&c>o&&!rm){el.classList.remove("pour");void el.offsetWidth;el.classList.add("pour");clearTimeout(t);t=setTimeout(()=>el.classList.remove("pour"),950)}};
el.querySelectorAll(".tb,.pl").forEach(b=>b.addEventListener("click",()=>set(c+1,true)));el.querySelector(".mn").addEventListener("click",()=>set(c-1,false));
return()=>clearTimeout(t)
});

