.uvq11-rose {
  --c1: #1d4ed8;
  --c2: #dc2626;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq11-rose {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 20em;
  height: 14em;
  border-radius: 1.6em;
  overflow: hidden;
  color: #fff;
  isolation: isolate;
  -webkit-user-select: none;
  user-select: none;
  --sx: 0;
  background: radial-gradient(40% 50% at 50% 35%,rgba(255,225,170,.16),transparent 70%),repeating-linear-gradient(0deg,transparent 0 2.2em,rgba(0,0,0,.28) 2.2em 2.3em),repeating-linear-gradient(90deg,transparent 0 3.4em,rgba(0,0,0,.18) 3.4em 3.5em),linear-gradient(#4b4640,#2d2925);
}

.uvq11-rose .rw {
  position: absolute;
  left: 50%;
  top: .55em;
  width: 9.4em;
  height: 9.4em;
  margin-left: -4.7em;
  filter: drop-shadow(0 0 .25em rgba(0,0,0,.6));
}

.uvq11-rose .pt {
  fill-opacity: .62;
  cursor: pointer;
  outline: 0;
  transition: fill-opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq11-rose .pt:hover {
  fill-opacity: .8;
}

.uvq11-rose .pt[aria-checked=true] {
  fill-opacity: .97;
}

.uvq11-rose .ld {
  fill: none;
  stroke: #17130f;
  stroke-width: 1.8;
  stroke-linejoin: round;
  pointer-events: none;
}

.uvq11-rose .pt:focus-visible {
  stroke: #fff;
  stroke-width: 2.2;
}

.uvq11-rose .fl {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 3.6em;
  overflow: hidden;
  background: linear-gradient(180deg,#5c544a,#7b7064);
  box-shadow: inset 0 .12em 0 rgba(0,0,0,.35);
}

.uvq11-rose .fl::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg,transparent 0 3em,rgba(0,0,0,.15) 3em 3.08em);
}

.uvq11-rose .pj {
  position: absolute;
  left: 50%;
  top: -1.6em;
  width: 9em;
  height: 9em;
  margin-left: -4.5em;
  opacity: .8;
  mix-blend-mode: screen;
  filter: blur(3px) saturate(1.6);
  transform: translateX(calc(var(--sx) * -2.5em)) perspective(12em) rotateX(64deg) scale(1.15,.9);
}

.uvq11-rose .bm {
  position: absolute;
  left: 50%;
