  height: 8em;
  margin-left: -4.5em;
  background: linear-gradient(180deg,color-mix(in srgb,var(--sel) 30%,rgba(255,250,230,.25)),transparent 95%);
  clip-path: polygon(18% 0,82% 0,100% 100%,0 100%);
