}

.uvq11-rose .nm {
  position: absolute;
  right: .9em;
  bottom: .8em;
  margin: 0;
  padding: .35em .8em;
  border-radius: 2em;
  font-size: .72em;
  font-weight: 700;
  letter-spacing: .04em;
