.uvq11-lava {
  --c1: #ff5a36;
  --c2: #5b21b6;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq11-lava {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 20em;
  height: 14em;
  border-radius: 1.6em;
  overflow: hidden;
  color: #fff;
  isolation: isolate;
  -webkit-user-select: none;
  user-select: none;
  background: radial-gradient(circle at 50% 50%,#5a3a24 0 .45em,transparent .5em) 0 0/2em 2em,radial-gradient(circle at 50% 50%,#4a2e1b 0 .3em,transparent .35em) 1em 1em/2em 2em,linear-gradient(#3b2518,#2a190f);
}

.uvq11-lava .df {
  position: absolute;
}

.uvq11-lava .gw {
  position: absolute;
  inset: 0;
  background: radial-gradient(40% 70% at 30% 55%,color-mix(in srgb,var(--c1) 55%,transparent),transparent 70%);
  opacity: 0;
  transition: opacity calc(1.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq11-lava.on .gw {
  opacity: 1;
}

.uvq11-lava .lp {
  position: absolute;
  left: 3.6em;
  top: .5em;
  width: 5.4em;
  height: 13em;
}

.uvq11-lava .cap {
  position: absolute;
  left: 1.55em;
  top: 0;
  width: 2.3em;
  height: 1.9em;
  clip-path: polygon(28% 0,72% 0,100% 100%,0 100%);
  background: linear-gradient(90deg,#6d5416,#f7e3a6 35%,#c9a24a 55%,#5e4612);
}

.uvq11-lava .vs {
  position: absolute;
  left: .2em;
  top: 1.85em;
  width: 5em;
  height: 7.5em;
  clip-path: polygon(32% 0,68% 0,97% 64%,88% 100%,12% 100%,3% 64%);
}

.uvq11-lava .lq {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg,color-mix(in srgb,var(--c2) 70%,#000),var(--c2) 45%,color-mix(in srgb,var(--c2) 60%,var(--c1)) 100%);
  transition: filter calc(1s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq11-lava:not(.on) .lq {
  filter: brightness(.45) saturate(.6);
}

.uvq11-lava .bl {
  position: absolute;
  inset: 0;
  filter: url(#uvq11-goo);
}

.uvq11-lava .bl::after {
  content: "";
  position: absolute;
  left: 5%;
  right: 5%;
  bottom: -.6em;
  height: 1.6em;
  border-radius: 50%;
  background: var(--c1);
}

.uvq11-lava .bl i {
  position: absolute;
  left: var(--x);
  bottom: -.2em;
  width: var(--s);
  height: var(--s);
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%,color-mix(in srgb,var(--c1) 60%,#ffd166),var(--c1));
  animation: uvq11-lava calc(var(--d) * 1s / var(--k)) ease-in-out infinite alternate;
  animation-delay: calc(var(--dl) * 1s / var(--k));
}

.uvq11-lava:not(.on) .bl i {
  animation-play-state: paused;
}

.uvq11-lava .gx {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg,rgba(255,255,255,.05) 0,rgba(255,255,255,.5) 13%,rgba(255,255,255,.08) 21%,transparent 40% 74%,rgba(255,255,255,.25) 85%,rgba(255,255,255,.04)),linear-gradient(180deg,rgba(255,255,255,.18),transparent 20%);
}

.uvq11-lava .bs {
  position: absolute;
  left: .1em;
  top: 9.3em;
  width: 5.2em;
  height: 3.4em;
  clip-path: polygon(12% 0,88% 0,100% 100%,0 100%);
  background: linear-gradient(90deg,#5e4612,#f7e3a6 30%,#c9a24a 50%,#7a5c1e 75%,#4a370d);
}

.uvq11-lava .bs::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
