.uvq11-lsl {
  --c1: #ffd60a;
  --c2: #ff7eb3;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --mg: 1.9;
  /* aumento de la lente */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq11-lsl {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 20em;
  height: 14em;
  border-radius: 1.6em;
  overflow: hidden;
  color: #fff;
  isolation: isolate;
  -webkit-user-select: none;
  user-select: none;
  --tw: 11.4em;
}

.uvq11-lsl .ph {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg,#4f5dff 0%,#c26fd8 30%,var(--c2) 46%,#ffd29d 56%,#ffd29d 57%);
  filter: brightness(calc(.45 + var(--br) * .8)) sepia(calc(var(--wm) * .55)) saturate(calc(.9 + var(--wm) * .5)) hue-rotate(calc(var(--wm) * -10deg));
}

.uvq11-lsl .sun {
  position: absolute;
  left: 58%;
  top: 38%;
  width: 3em;
  height: 3em;
  border-radius: 50%;
  background: radial-gradient(circle,#fff8d6 0 35%,#ffd29d 60%,transparent 72%);
}

.uvq11-lsl .m1 {
  position: absolute;
  left: -5%;
  right: 35%;
  top: 30%;
  height: 27%;
  background: #5a3f86;
  clip-path: polygon(0 100%,30% 20%,48% 60%,70% 0,100% 100%);
}

.uvq11-lsl .m2 {
  position: absolute;
  left: 30%;
  right: -5%;
  top: 36%;
  height: 21%;
  background: #3e2c66;
  clip-path: polygon(0 100%,35% 10%,60% 55%,80% 25%,100% 100%);
}

.uvq11-lsl .lk {
  position: absolute;
  left: 0;
  right: 0;
  top: 57%;
  bottom: 0;
  background: repeating-linear-gradient(180deg,rgba(255,255,255,.18) 0 1px,transparent 1px .5em),linear-gradient(180deg,#ffb48a,#6f4fa8 55%,#2d2a6b);
}

.uvq11-lsl .pn {
  position: absolute;
  left: .8em;
  right: .8em;
  bottom: .8em;
  padding: .7em 1em .8em;
  border-radius: 1.3em;
  background: rgba(255,255,255,.16);
  -webkit-backdrop-filter: blur(14px) saturate(1.8);
  backdrop-filter: blur(14px) saturate(1.8);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.55),inset 0 0 0 1px rgba(255,255,255,.22),0 .8em 2em -.6em rgba(0,0,0,.35);
}

.uvq11-lsl .ti {
  margin: 0 0 .35em;
  font-size: .72em;
  font-weight: 700;
  opacity: .85;
}

.uvq11-lsl .rw {
  display: flex;
  align-items: center;
  gap: .6em;
  height: 2.2em;
}

.uvq11-lsl .rw>svg {
  flex: none;
  width: 1.15em;
  height: 1.15em;
}

.uvq11-lsl .rw output {
  flex: none;
  width: 1.8em;
  text-align: right;
  font-size: .8em;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.uvq11-lsl .sl {
  position: relative;
  flex: none;
  width: var(--tw);
  height: 2.2em;
  cursor: pointer;
  touch-action: none;
  outline: 0;
}

.uvq11-lsl .tk,.uvq11-lsl .tc {
  position: absolute;
  top: 50%;
  height: .42em;
  margin-top: -.21em;
  border-radius: 1em;
  background: rgba(255,255,255,.32);
  overflow: hidden;
}

.uvq11-lsl .tk {
  left: 0;
  right: 0;
}

.uvq11-lsl .fi {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: calc(var(--v) * 100%);
  background: var(--c1);
}

.uvq11-lsl .th {
  position: absolute;
  left: calc(var(--v) * 100%);
  top: 50%;
  width: 1.9em;
  height: 1.15em;
  border-radius: 1em;
  transform: translate(-50%,-50%);
  background: #fff;
  box-shadow: 0 .15em .4em rgba(0,0,0,.25);
  transition: width calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1),height calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1),background calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),box-shadow calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq11-lsl .lz {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  overflow: hidden;
  opacity: 0;
  transition: opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq11-lsl .tc {
  left: calc(50% - var(--v) * var(--tw));
  width: var(--tw);
  transform-origin: calc(var(--v) * var(--tw)) 50%;
  transform: scale(var(--mg));
  background: rgba(255,255,255,.45);
}

.uvq11-lsl .sl.dr .th {
  width: 3.6em;
  height: 2.3em;
  background: rgba(255,255,255,.08);
  -webkit-backdrop-filter: blur(.5px) saturate(1.6) brightness(1.1);
  backdrop-filter: blur(.5px) saturate(1.6) brightness(1.1);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.75),inset 0 .2em .35em rgba(255,255,255,.55),inset 0 -.25em .4em rgba(0,0,0,.18),inset .15em 0 .25em rgba(255,60,150,.3),inset -.15em 0 .25em rgba(0,200,255,.3),0 .5em 1.2em -.4em rgba(0,0,0,.4);
}

.uvq11-lsl .sl.dr .lz {
  opacity: 1;
}

.uvq11-lsl .sl:focus-visible .th {
  outline: 2px solid #fff;
  outline-offset: 2px;
}

@media (prefers-reduced-motion:reduce) {
  .uvq11-lsl,.uvq11-lsl *,.uvq11-lsl *::before,.uvq11-lsl *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

