document.querySelectorAll(".uvq11-lsl").forEach(el => {
  const ss=[...el.querySelectorAll(".sl")],ts=[];
ss.forEach(s=>{const o=s.parentElement.querySelector("output"),k=s.dataset.k;let v=parseFloat(s.style.getPropertyValue("--v"))||0;
const set=n=>{v=Math.max(0,Math.min(1,n));const p=Math.round(v*100);s.style.setProperty("--v",v.toFixed(4));el.style.setProperty("--"+k,v.toFixed(3));o.textContent=String(p);s.setAttribute("aria-valuenow",String(p));s.setAttribute("aria-valuetext",p+" %")};
const at=e=>{const r=s.getBoundingClientRect();set((e.clientX-r.left)/r.width)};
s.addEventListener("pointerdown",e=>{s.setPointerCapture(e.pointerId);s.classList.add("dr");at(e)});
s.addEventListener("pointermove",e=>{if(s.hasPointerCapture(e.pointerId))at(e)});
const up=()=>s.classList.remove("dr");s.addEventListener("pointerup",up);s.addEventListener("pointercancel",up);s.addEventListener("blur",up);
s.addEventListener("keydown",e=>{const d={ArrowRight:.05,ArrowUp:.05,ArrowLeft:-.05,ArrowDown:-.05,PageUp:.2,PageDown:-.2}[e.key];if(d===undefined&&e.key!=="Home"&&e.key!=="End")return;e.preventDefault();set(e.key==="Home"?0:e.key==="End"?1:v+d);s.classList.add("dr");clearTimeout(s._t);s._t=setTimeout(up,800);ts.push(s._t)})});
ts.push(setTimeout(()=>{ss[0].classList.add("dr");ts.push(setTimeout(()=>ss[0].classList.remove("dr"),1800))},400));
return()=>ts.forEach(clearTimeout)
});

