.uvq11-ico {
  --c1: #ff8a3d;
  --c2: #2563eb;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --bl: 8px;
  /* desenfoque */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

@property --uvq11-ia {
  syntax: "<angle>";
  inherits: true;
  initial-value: 135deg;
}

.uvq11-ico {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 20em;
  height: 14em;
  border-radius: 1.6em;
  overflow: hidden;
  color: #fff;
  isolation: isolate;
  -webkit-user-select: none;
  user-select: none;
  animation: uvq11-ico calc(8s / var(--k)) linear infinite;
}

.uvq11-ico .wp {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 74% 30%,transparent 2.2em,rgba(255,255,255,.85) 2.25em 2.4em,transparent 2.45em),radial-gradient(1.1em 1.1em at 22% 66%,#ffe066 95%,transparent),repeating-linear-gradient(125deg,transparent 0 1.6em,rgba(255,255,255,.12) 1.6em 1.75em),radial-gradient(70% 60% at 18% 12%,var(--c1),transparent 62%),radial-gradient(60% 70% at 88% 45%,#ff4f8b,transparent 62%),radial-gradient(80% 60% at 45% 105%,var(--c2),transparent 70%),linear-gradient(160deg,#1a1446,#0e2a5c);
}

.uvq11-ico .gr {
  position: absolute;
  left: 50%;
  top: 1.1em;
  display: grid;
  grid-template-columns: repeat(4,3.2em);
  gap: .55em 1.15em;
  transform: translateX(-50%);
}

.uvq11-ico .ap {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  justify-items: center;
  gap: .3em;
  transition: transform calc(0.35s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq11-ico .ap:active {
  transform: scale(.88);
}

.uvq11-ico .ap:focus-visible {
  outline: 0;
}

.uvq11-ico .ap:focus-visible .gl {
  outline: 2px solid #fff;
  outline-offset: 3px;
}

.uvq11-ico .gl {
  position: relative;
  display: grid;
  place-items: center;
