  height: 3.2em;
  border-radius: .9em;
  background: rgba(255,255,255,.08);
  -webkit-backdrop-filter: blur(var(--bl)) saturate(1.8) brightness(1.15);
  backdrop-filter: blur(var(--bl)) saturate(1.8) brightness(1.15);
  box-shadow: 0 .5em .9em -.45em rgba(0,0,0,.45),inset 0 0 .7em rgba(255,255,255,.1);
  transition: background calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq11-ico .gl::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1.4px;
  -webkit-mask: linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);
