}

.uvq11-ico .gl::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(calc(var(--ang,var(--uvq11-ia)) + 180deg),rgba(255,255,255,.28),transparent 48%);
  pointer-events: none;
}

.uvq11-ico .gl svg {
  width: 1.55em;
  height: 1.55em;
  color: rgba(255,255,255,.95);
  filter: drop-shadow(0 .06em .12em rgba(0,0,0,.3));
  transition: color calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq11-ico .nm {
  font-size: .56em;
  font-weight: 600;
  text-shadow: 0 1px 3px rgba(0,0,0,.5);
}

.uvq11-ico:has(input[value=t]:checked) .gl {
  background: color-mix(in srgb,var(--c1) 42%,transparent);
}

.uvq11-ico:has(input[value=t]:checked) .gl svg {
  color: color-mix(in srgb,var(--c1) 25%,#fff);
}

.uvq11-ico .md {
  position: absolute;
  left: 50%;
