  padding: .22em;
  border-radius: 2em;
  transform: translateX(-50%);
  background: rgba(255,255,255,.14);
  -webkit-backdrop-filter: blur(12px) saturate(1.6);
  backdrop-filter: blur(12px) saturate(1.6);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.45),inset 0 0 0 1px rgba(255,255,255,.2);
}

.uvq11-ico .md label {
  position: relative;
