  font-size: .68em;
  font-weight: 700;
  transition: all calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq11-ico .md input:checked+span {
  color: #1d1d1f;
  background: rgba(255,255,255,.92);
  box-shadow: 0 .15em .4em rgba(0,0,0,.2);
}

.uvq11-ico .md input:focus-visible+span {
  outline: 2px solid #fff;
  outline-offset: 2px;
}

@keyframes uvq11-ico {
  to {
    --uvq11-ia: 495deg;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq11-ico,.uvq11-ico *,.uvq11-ico *::before,.uvq11-ico *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

